"""Tables and other displays of structured data

A table is a native `table`, styled plainly by the base layer, and the browser already gives it its structure: a caption, a head, a body, and a foot. This module adds the data table: a frame, a raised surface that the table fills and that scrolls sideways when the table is wider than the page, and the head band and single-line cells of a table of figures.

Docs: https://AnswerDotAI.github.io/answerui/data.html.md"""

# AUTOGENERATED! DO NOT EDIT! File to edit: ../nbs/13_data.ipynb.

# %% auto #0
__all__ = ['Table']

# %% ../nbs/13_data.ipynb #1a63437d
from fasthtml.common import Div, Caption, Thead, Tbody, Tfoot, Tr, Th, Td
import fasthtml.components as fc
from .registry import hypelt
from .demo import example
import answerui.base  # the base layer this frame extends

# %% ../nbs/13_data.ipynb #ac5f7b09
_frame_css = r'''
[frame] {
  --face: var(--n-3); background: var(--face); overflow-x: auto; contain: inline-size;
  border: 1px solid var(--n-1); border-radius: var(--radius); box-shadow: var(--raised);
  > table { inline-size: 100%; }
  :is(th, td) { white-space: nowrap; }
  tbody tr:first-child > * { border-block-start: 1px solid var(--n-1); }
  thead th { background: var(--n-2); color: var(--n1); font: var(--weight) var(--text-1) var(--font-mono); text-transform: uppercase; letter-spacing: .08em; border-block-end: 0; }
}
'''

@hypelt(sel='[frame]', layer='components', css=_frame_css)
def Table(*c, **attrs):
    "A table in a frame: a bordered surface it fills, which scrolls sideways when the table is wider than the page"
    return Div(fc.Table(*c, **attrs), frame=True)


# %% ../nbs/13_data.ipynb #cf26ac6f
@example(Table)
def _table_example():
    rows = [('North', '1,204', '38,410', '31.90'), ('South', '862', '27,955', '32.43'), ('West', '1,531', '50,112', '32.73')]
    def row(nm, *figs): return Tr(Td(nm), *[Td(f, num=True) for f in figs])
    head = Thead(Tr(Th('Region'), Th('Orders', num=True), Th('Revenue', num=True), Th('Average', num=True)))
    foot = Tfoot(Tr(Th('Total'), Td('3,597', num=True), Td('116,477', num=True), Td('32.38', num=True)))
    return Table(Caption('Revenue and average order in US$, Q3'), head, Tbody(*[row(*r) for r in rows]), foot)
